{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.grn_issues_joined AS WITH grn_base AS ( SELECT ORIGIN, UNIQUEKEY, ORDER_DATE, EDD, ORDER_NUMBER, SUPPLIER_ORDER_NO, TRANSFER_BRANCH_CODE, TO_PARTY AS BRANCH_NAME, FROM_PARTY AS VENDOR_GRN, PARTY_USER_CODE, BRANCH_SHORT_NAME, VOUCH_CODE AS GRN_NUMBER, ORDER_PREFIX, ACTION_CODE, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, AGENT_NAME, LOGIC_USER_CODE, LOT_NUMBER, PO_MRP, PENDING_QTY, TOTAL_QTY, TXN_CODE FROM snitch_db.maplemonk.logic_purchase_order ), issue_base AS ( SELECT ID AS ISSUE_ID, CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, QTY AS ISSUE_QTY, SKU, Issue AS ISSUE, SUB_ISSUE AS SUB_ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, PO_NUMBER, INVOICE_NUMBER, CREATED_AT AS ISSUE_CREATED_AT, CREATED_BY, LAST_UPDATED_AT AS ISSUE_LAST_UPDATED_AT FROM snitch_db.maplemonk.issues_factory_sorted ) SELECT g.UNIQUEKEY, g.ORIGIN, g.ORDER_DATE, g.EDD, g.ORDER_NUMBER, g.SUPPLIER_ORDER_NO, g.TRANSFER_BRANCH_CODE, g.BRANCH_NAME, g.BRANCH_SHORT_NAME, g.VENDOR_GRN, g.PARTY_USER_CODE, g.GRN_NUMBER, g.ORDER_PREFIX, g.ACTION_CODE, g.NET_ORDER_AMOUNT, g.ORDER_AMOUNT, g.TOTAL_TAX, g.AGENT_NAME, g.LOGIC_USER_CODE, g.LOT_NUMBER AS PO_NUMBER_GRN, g.PO_MRP, g.PENDING_QTY, g.TOTAL_QTY, g.TXN_CODE, i.ISSUE_ID, i.ISSUE_CREATED_AT_DATE, i.ISSUE_UPDATED_AT_DATE, i.ISSUE_QTY, i.SKU, i.ISSUE, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.INVOICE_NUMBER, i.ISSUE_CREATED_AT, i.CREATED_BY, i.ISSUE_LAST_UPDATED_AT, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM grn_base g LEFT JOIN issue_base i ON TRIM(i.PO_NUMBER) = TRIM(g.LOT_NUMBER);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            